#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = 1e9 + 9;

struct Edge {
    int u, v, flow, cap;
    Edge(int u, int v, int f, int c) : u(u), v(v), flow(f), cap(c) {}
};

int src, snk;
vector<vector<int>> adj;
vector<Edge> edges;

void add_edge(int u, int v, int cap) {
    adj[u].push_back(edges.size());
    edges.emplace_back(u, v, 0, cap);
    adj[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, 0);
}

int ptr[1001], dist[1001];

bool bfs() {
    memset(dist, -1, sizeof(dist));
    dist[src] = 0;
    queue<int> q;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            auto& e = edges[id];
            if (dist[e.v] == -1 && e.flow < e.cap) {
                dist[e.v] = dist[u] + 1;
                q.push(e.v);
                if (e.v == snk) return true;
            }
        }
    }
    return false;
}

ll dfs(int u, ll flow) {
    if (u == snk || flow == 0) return flow;
    for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
        int id = adj[u][i];
        auto& e = edges[id];
        if (dist[e.v] != dist[u] + 1) continue;
        ll pushed = dfs(e.v, min(flow, (ll)e.cap - e.flow));
        if (pushed) {
            e.flow += pushed;
            edges[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

ll dinic() {
    ll flow = 0;
    while (bfs()) {
        memset(ptr, 0, sizeof(ptr));
        ll pushed;
        while ((pushed = dfs(src, INF)) > 0)
            flow += pushed;
    }
    return flow;
}

string scientists[101], reactors[101];
bool reachable[10][10][10][10];
int visited[101][101];
int unusable_at[10][10];
int n, m;

bool valid(int r, int c) {
    return r >= 0 && c >= 0 && r < n && c < m;
}

int id(int x, int y) { return 1 + m * x + y; }

int main() {
    ios::sync_with_stdio(false);
    int T;
    cin >> n >> T;
    ++T;
    m = n;
    snk = m * m * 2 + 1;
    src = 0;
    adj.resize(m * m * 2 + 2);
    queue<pair<int, int>> q;
    for (int i = 0; i < n; ++i) cin >> scientists[i];
    for (int i = 0; i < n; ++i) {
        cin >> reactors[i];
        for (int j = 0; j < m; ++j) {
            unusable_at[i][j] = INF;
            if (reactors[i][j] == 'Z') {
                q.push({i, j});
                unusable_at[i][j] = 1;
            }
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj)
                if (abs(di) + abs(dj) == 1) {
                    int nx = x + di, ny = y + dj;
                    if (valid(nx, ny) && unusable_at[nx][ny] == INF && scientists[nx][ny] != 'Y') {
                        unusable_at[nx][ny] = unusable_at[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
    }
    for (int x = 0; x < n; ++x)
        for (int y = 0; y < m; ++y) {
            if (scientists[x][y] >= '1' && scientists[x][y] <= '9')
                add_edge(src, id(x, y), scientists[x][y] - '0');
            if (reactors[x][y] >= '1' && reactors[x][y] <= '9')
                add_edge(n * n + id(x, y), snk, reactors[x][y] - '0');
            for (int X = 0; X < n; ++X)
                for (int Y = 0; Y < m; ++Y) {
                    if (scientists[x][y] == 'Y' || scientists[x][y] == 'Z' ||
                        reactors[X][Y] == 'Y' || reactors[X][Y] == 'Z')
                        continue;
                    memset(visited, 0, sizeof(visited));
                    queue<tuple<int, int, int>> bfsq;
                    bfsq.emplace(x, y, 1);
                    visited[x][y] = 1;
                    while (!bfsq.empty()) {
                        auto [cx, cy, t] = bfsq.front(); bfsq.pop();
                        if (cx == X && cy == Y) {
                            visited[cx][cy] = 1;
                            break;
                        }
                        if (t >= unusable_at[cx][cy] || t >= T) continue;
                        for (int di = -1; di <= 1; ++di)
                            for (int dj = -1; dj <= 1; ++dj)
                                if (abs(di) + abs(dj) == 1) {
                                    int nx = cx + di, ny = cy + dj;
                                    if (valid(nx, ny) && !visited[nx][ny] &&
                                        scientists[nx][ny] != 'Y' && scientists[nx][ny] != 'Z' &&
                                        t + 1 <= unusable_at[nx][ny]) {
                                        visited[nx][ny] = 1;
                                        bfsq.emplace(nx, ny, t + 1);
                                    }
                                }
                    }
                    if (visited[X][Y])
                        add_edge(id(x, y), n * n + id(X, Y), INF);
                }
        }
    cout << dinic() << '\n';
}
